{
  "claims": [
    {
      "text": "Continue continuous cardiopulmonary monitoring (telemetry/SpO2) with current alarm limits, given tachycardia, tachypnea, and SpO2 92-97% on supplemental oxygen.",
      "action_type": "monitored",
      "target": "cardiopulmonary status"
    },
    {
      "text": "Assess and manage leukocytosis (WBC 19 K/uL) with clinical evaluation for infection and, if indicated, cultures and antimicrobial therapy.",
      "action_type": "assessment_performed",
      "target": "leukocytosis"
    },
    {
      "text": "Perform a focused respiratory assessment and consider adjusting supplemental oxygen to maintain SpO2 above the 92% low alarm limit.",
      "action_type": "assessment_performed",
      "target": "oxygenation"
    },
    {
      "text": "Reassess pain and administer analgesia as needed, given moderate pain scores.",
      "action_type": "administered",
      "target": "pain"
    },
    {
      "text": "Provide venous thromboembolism prophylaxis with subcutaneous heparin 5000 units, as ordered, unless contraindicated.",
      "action_type": "administered",
      "target": "VTE prophylaxis"
    },
    {
      "text": "Maintain fall precautions and mobility assistance given weak gait/transferring and bed rest status.",
      "action_type": "monitored",
      "target": "fall risk"
    },
    {
      "text": "Continue monitoring vital signs per ICU protocol, with attention to heart rate, blood pressure, respiratory rate, and temperature.",
      "action_type": "monitored",
      "target": "vital signs"
    },
    {
      "text": "Repeat basic metabolic panel and complete blood count within 24 hours to trend electrolytes, renal function, and leukocytosis.",
      "action_type": "specimen_collected",
      "target": "laboratory monitoring"
    },
    {
      "text": "Maintain nothing-by-mouth status pending further evaluation, with intravenous fluid maintenance as ordered.",
      "action_type": "ordered",
      "target": "nutrition/fluid management"
    },
    {
      "text": "Continue ondansetron as needed for nausea, with reassessment of symptoms.",
      "action_type": "ordered",
      "target": "nausea"
    }
  ]
}

{
  "claims": [
    {
      "text": "Maintain continuous cardiorespiratory monitoring with alarms and ST-segment monitoring for the next 24 hours given tachycardia, borderline hypotension, and oxygen requirement.",
      "action_type": "monitored",
      "target": "cardiorespiratory status"
    },
    {
      "text": "Recheck serum magnesium and potassium within 24 hours given hypomagnesemia (1.5 mg/dL) and borderline low potassium (3.5 mEq/L).",
      "action_type": "specimen_collected",
      "target": "serum magnesium and potassium"
    },
    {
      "text": "Assess and manage pain with the existing multimodal regimen, targeting a pain score below 4.",
      "action_type": "assessment_performed",
      "target": "pain"
    },
    {
      "text": "Monitor blood glucose and treat hyperglycemia (fingerstick 161 mg/dL, serum glucose 146-152 mg/dL) per protocol.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Continue supplemental oxygen at 2 L/min via nasal cannula and titrate to maintain SpO2 above 92%.",
      "action_type": "therapy_continued",
      "target": "supplemental oxygen"
    },
    {
      "text": "Monitor white blood cell count trend (17-20.1 K/uL) and assess for infection source.",
      "action_type": "monitored",
      "target": "white blood cell count and infection status"
    },
    {
      "text": "Implement aspiration precautions and swallowing evaluation given documented difficulty swallowing.",
      "action_type": "assessment_performed",
      "target": "swallowing safety"
    },
    {
      "text": "Perform Braden-based pressure injury prevention with repositioning and skin care given bedfast activity and friction/shear risk.",
      "action_type": "treatment_performed",
      "target": "skin integrity"
    },
    {
      "text": "Assess and manage anxiety (Richmond-RAS +1) with nonpharmacologic measures and as-needed anxiolysis per existing orders.",
      "action_type": "assessment_performed",
      "target": "anxiety"
    },
    {
      "text": "Maintain fall precautions with bed rest and assist with all transfers given bedfast status and IV access.",
      "action_type": "treatment_performed",
      "target": "fall prevention"
    }
  ]
}

{
  "claims": [
    {
      "text": "Reassess and manage hypotension (recent systolic BP 89-99 mmHg, MAP 62-67 mmHg) with appropriate fluid resuscitation and hemodynamic monitoring.",
      "action_type": "monitored",
      "target": "hemodynamic status"
    },
    {
      "text": "Continue and reassess broad-spectrum antibiotic therapy (levofloxacin, metronidazole, oral vancomycin) given leukocytosis (WBC 22.4-27.9 K/uL).",
      "action_type": "therapy_continued",
      "target": "antimicrobial therapy"
    },
    {
      "text": "Monitor oxygen saturation and respiratory status; patient requires supplemental O2 at 4 L/min with SpO2 98-99%.",
      "action_type": "monitored",
      "target": "respiratory status"
    },
    {
      "text": "Repeat basic metabolic panel to reassess hyponatremia (Na 128-133 mEq/L), hypocalcemia (total Ca 7.0-7.8 mg/dL), and metabolic acidosis (bicarbonate 18-20 mEq/L, anion gap 15-17).",
      "action_type": "specimen_collected",
      "target": "serum electrolytes and acid-base status"
    },
    {
      "text": "Trend lactate (1.5-2.4 mmol/L) to assess for ongoing hypoperfusion.",
      "action_type": "monitored",
      "target": "lactate"
    },
    {
      "text": "Monitor hemoglobin/hematocrit (Hgb 9.3-10.2 g/dL, Hct 28.7-32.3%) and assess for bleeding or need for transfusion.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Replete and monitor magnesium and phosphorus (magnesium 2.7 mg/dL, phosphate 2.2-3.8 mg/dL) as indicated.",
      "action_type": "monitored",
      "target": "magnesium and phosphate"
    },
    {
      "text": "Monitor blood glucose (fingerstick 113 mg/dL, serum 148 mg/dL) and continue glycemic control.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Implement fall precautions given high fall risk (history of falls, bed rest, IV access, altered mental status).",
      "action_type": "assessment_performed",
      "target": "fall risk"
    },
    {
      "text": "Perform aspiration precautions and oral care given mildly impaired swallow and increased secretions (OCAT findings).",
      "action_type": "assessment_performed",
      "target": "swallowing and aspiration risk"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue phenylephrine infusion for hemodynamic support, titrating to maintain adequate mean arterial pressure.",
      "action_type": "therapy_continued",
      "target": "phenylephrine infusion"
    },
    {
      "text": "Continue unfractionated heparin infusion for acute coronary syndrome, with monitoring of coagulation parameters.",
      "action_type": "therapy_continued",
      "target": "heparin infusion"
    },
    {
      "text": "Obtain serial troponin and CK-MB measurements to evaluate rising cardiac biomarkers.",
      "action_type": "specimen_collected",
      "target": "cardiac biomarkers (troponin, CK-MB)"
    },
    {
      "text": "Administer intravenous insulin and monitor fingerstick glucose frequently for severe hyperglycemia.",
      "action_type": "ordered",
      "target": "insulin and glucose monitoring"
    },
    {
      "text": "Monitor lactate levels and hemodynamics closely given lactic acidosis and hypotension.",
      "action_type": "monitored",
      "target": "lactate and hemodynamic status"
    },
    {
      "text": "Continue supplemental oxygen to maintain oxygen saturation above target.",
      "action_type": "therapy_continued",
      "target": "supplemental oxygen"
    },
    {
      "text": "Monitor urine output and renal function given acute kidney injury and diuretic use.",
      "action_type": "monitored",
      "target": "urine output and renal function"
    },
    {
      "text": "Continue broad-spectrum antimicrobial therapy, including oral vancomycin, for suspected infection.",
      "action_type": "therapy_continued",
      "target": "antimicrobial therapy"
    },
    {
      "text": "Perform continuous cardiac monitoring and obtain 12-lead ECG for ischemic evaluation.",
      "action_type": "assessment_performed",
      "target": "cardiac monitoring and ECG"
    },
    {
      "text": "Maintain bedrest with fall precautions and pressure ulcer prevention given immobility.",
      "action_type": "monitored",
      "target": "bedrest and skin integrity"
    }
  ]
}

{
  "claims": [
    {
      "text": "Assess and manage anemia with hemoglobin 7.7 g/dL and hematocrit 27.6%, including evaluation for bleeding and consideration of transfusion per threshold.",
      "action_type": "assessment_performed",
      "target": "anemia"
    },
    {
      "text": "Monitor for alcohol withdrawal given CIWA tremor and history of ETOH use, with symptom-triggered benzodiazepine therapy as needed.",
      "action_type": "monitored",
      "target": "alcohol withdrawal"
    },
    {
      "text": "Replete potassium given serum potassium 3.4 mEq/L.",
      "action_type": "ordered",
      "target": "potassium"
    },
    {
      "text": "Replete magnesium given serum magnesium 1.8 mg/dL.",
      "action_type": "ordered",
      "target": "magnesium"
    },
    {
      "text": "Monitor blood glucose given fingerstick glucose values of 208 and 294 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Continue telemetry and vital sign monitoring with alarms for heart rate, blood pressure, respiratory rate, and oxygen saturation.",
      "action_type": "monitored",
      "target": "vital signs"
    },
    {
      "text": "Maintain fall precautions given history of falls and bed rest status.",
      "action_type": "monitored",
      "target": "fall risk"
    },
    {
      "text": "Continue D5NS infusion at 5 mL/hour.",
      "action_type": "therapy_continued",
      "target": "intravenous fluids"
    },
    {
      "text": "Perform nutritional assessment given Braden nutrition score of 2 (probably inadequate).",
      "action_type": "assessment_performed",
      "target": "nutrition"
    },
    {
      "text": "Continue venous thromboembolism prophylaxis with subcutaneous heparin 5000 units.",
      "action_type": "therapy_continued",
      "target": "VTE prophylaxis"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with lung-protective settings and titrate to improve respiratory acidosis (pH 7.25-7.27, pCO2 54-55).",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Monitor arterial blood gases serially to assess the adequacy of ventilation and acid-base status.",
      "action_type": "monitored",
      "target": "arterial blood gas"
    },
    {
      "text": "Monitor continuous pulse oximetry and titrate supplemental oxygen to maintain SpO2 above the desaturation limit.",
      "action_type": "monitored",
      "target": "oxygen saturation"
    },
    {
      "text": "Monitor blood pressure and heart rate closely given hypotension and tachycardia, with escalation of care if hypotension persists.",
      "action_type": "monitored",
      "target": "hemodynamic status"
    },
    {
      "text": "Obtain daily chest imaging if not already done to evaluate for pulmonary pathology contributing to hypercapnia.",
      "action_type": "imaging_performed",
      "target": "chest radiograph"
    },
    {
      "text": "Continue analgesia via PCA and epidural as prescribed, assessing pain and sedation levels regularly.",
      "action_type": "therapy_continued",
      "target": "pain management"
    },
    {
      "text": "Monitor magnesium and potassium levels and replace electrolytes as needed, given prior hypomagnesemia and ongoing supplementation.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Assess and manage elevated intracranial pressure risk or neurologic status with regular neurologic checks.",
      "action_type": "assessment_performed",
      "target": "neurologic status"
    },
    {
      "text": "Continue venous thromboembolism prophylaxis with heparin or mechanical prophylaxis as ordered.",
      "action_type": "therapy_continued",
      "target": "VTE prophylaxis"
    },
    {
      "text": "Maintain head-of-bed elevation and provide pulmonary hygiene (incentive spirometry, cough/deep breathing) to prevent atelectasis.",
      "action_type": "therapy_continued",
      "target": "pulmonary hygiene"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with lung-protective settings and tit-rate weaning per spontaneous breathing trial readiness.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue propofol and fentanyl sedation titrated to goal RASS -1, reassessing sedation and delirium (CAM-ICU) status.",
      "action_type": "therapy_continued",
      "target": "sedation"
    },
    {
      "text": "Obtain serial arterial blood gases to monitor severe metabolic acidosis and lactate clearance.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Continue intravenous sodium bicarbonate therapy for severe metabolic acidosis with bicarbonate 14 mEq/L and base excess -9 to -12.",
      "action_type": "therapy_continued",
      "target": "sodium bicarbonate"
    },
    {
      "text": "Monitor coagulation parameters (PT/INR, PTT, fibrinogen, platelets) given INR 1.8-2.0, fibrinogen 100-216 mg/dL, and platelets 60-80 K/uL.",
      "action_type": "monitored",
      "target": "coagulation"
    },
    {
      "text": "Monitor hemoglobin and hematocrit for worsening anemia (hemoglobin 9.7-10.4 g/dL, hematocrit 28-29%).",
      "action_type": "monitored",
      "target": "hemoglobin/hematocrit"
    },
    {
      "text": "Continue enteral/parenteral nutrition support and monitor albumin (2.7-2.9 g/dL) and nutrition status.",
      "action_type": "therapy_continued",
      "target": "nutrition"
    },
    {
      "text": "Perform daily assessment for ICU-acquired weakness and delirium with CAM-ICU and Richmond-RAS.",
      "action_type": "assessment_performed",
      "target": "delirium and weakness assessment"
    },
    {
      "text": "Monitor hemodynamics (heart rate, arterial blood pressure, central venous pressure) given tachycardia and borderline blood pressure.",
      "action_type": "monitored",
      "target": "hemodynamics"
    },
    {
      "text": "Provide pressure injury prevention with repositioning and skin care for Braden-identified risk and existing impaired skin area.",
      "action_type": "treatment_performed",
      "target": "pressure injury prevention"
    }
  ]
}

{
  "claims": [
    {
      "text": "Maintain continuous renal replacement therapy (CRRT) with documented dialysis catheter and Prismasate/citrate anticoagulation.",
      "action_type": "therapy_continued",
      "target": "continuous renal replacement therapy"
    },
    {
      "text": "Continue invasive mechanical ventilation via CPAP/PSV with PEEP 10 cmH2O and titrate inspired oxygen to maintain SpO2 ≥ 92%.",
      "action_type": "therapy_continued",
      "target": "invasive mechanical ventilation"
    },
    {
      "text": "Continue norepinephrine infusion and titrate to maintain MAP ≥ 65 mmHg.",
      "action_type": "therapy_continued",
      "target": "norepinephrine infusion"
    },
    {
      "text": "Obtain repeat arterial blood gas to reassess acid-base status and oxygenation.",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Monitor platelet count and coagulation profile given severe thrombocytopenia (platelets 12–29 K/uL).",
      "action_type": "monitored",
      "target": "platelet count and coagulation"
    },
    {
      "text": "Monitor serum potassium and magnesium and replete as needed given hypokalemia and hypomagnesemia.",
      "action_type": "monitored",
      "target": "serum potassium and magnesium"
    },
    {
      "text": "Monitor blood glucose and continue insulin infusion to maintain glycemic control.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Monitor lactate clearance to assess adequacy of resuscitation.",
      "action_type": "monitored",
      "target": "lactate"
    },
    {
      "text": "Perform daily sedation interruption and delirium assessment (CAM-ICU) given positive screen.",
      "action_type": "assessment_performed",
      "target": "sedation and delirium assessment"
    },
    {
      "text": "Maintain VTE prophylaxis and consider transfusion thresholds in the setting of severe thrombocytopenia.",
      "action_type": "ordered",
      "target": "VTE prophylaxis and transfusion plan"
    }
  ]
}

{
  "claims": [
    {
      "text": "Assess and manage hyperkalemia, with serum potassium up to 6.2 mEq/L, including ECG monitoring and consideration of potassium-lowering therapy.",
      "action_type": "assessment_performed",
      "target": "serum potassium"
    },
    {
      "text": "Monitor blood pressure closely and titrate phenylephrine infusion to maintain adequate mean arterial pressure, given recent MAP 56-68 mmHg.",
      "action_type": "monitored",
      "target": "blood pressure"
    },
    {
      "text": "Continue mechanical ventilation with current settings and monitor respiratory status, including spontaneous breathing trials readiness.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Monitor hemoglobin and hematocrit for anemia, with recent hemoglobin 11.1 g/dL, and transfuse if clinically indicated.",
      "action_type": "monitored",
      "target": "hemoglobin"
    },
    {
      "text": "Monitor coagulation parameters (INR, PTT, fibrinogen) and platelet count, given coagulopathy with INR up to 1.8 and platelets 131 K/uL.",
      "action_type": "monitored",
      "target": "coagulation status"
    },
    {
      "text": "Assess and manage pain, with reported pain level up to 10, using multimodal analgesia.",
      "action_type": "assessment_performed",
      "target": "pain"
    },
    {
      "text": "Monitor blood glucose and continue insulin infusion as needed, with glucose levels ranging 87-144 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Monitor arterial blood gases and lactate, with lactate 2.8 mmol/L and pH 7.33-7.35, to assess oxygenation and acid-base status.",
      "action_type": "monitored",
      "target": "arterial blood gas"
    },
    {
      "text": "Perform daily sedation interruption and assess neurological status, with Richmond-RAS Scale fluctuating from -5 to +3.",
      "action_type": "assessment_performed",
      "target": "sedation level"
    },
    {
      "text": "Implement fall precautions and pressure ulcer prevention, given bed rest and Braden scores indicating risk.",
      "action_type": "assessment_performed",
      "target": "fall risk"
    }
  ]
}

{
  "claims": [
    {
      "text": "Transfuse packed red blood cells for severe anemia (hemoglobin 6.8-7.1 g/dL) with blood transfusion consent documented.",
      "action_type": "ordered",
      "target": "packed red blood cells"
    },
    {
      "text": "Monitor arterial blood pressure closely and support with vasopressor (phenylephrine infusion) for hypotension (MAP 59-67 mmHg).",
      "action_type": "monitored",
      "target": "arterial blood pressure and vasopressor support"
    },
    {
      "text": "Continue mechanical ventilation with lung-protective settings and titrate FiO2 to maintain adequate oxygenation (PaO2 141-471 mmHg, SpO2 96-98%).",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Monitor and manage temporary pacemaker settings (ventricular rate 52 bpm) with continuous ECG monitoring.",
      "action_type": "monitored",
      "target": "temporary pacemaker"
    },
    {
      "text": "Recheck hemoglobin and hematocrit to assess response to transfusion and ongoing anemia.",
      "action_type": "specimen_collected",
      "target": "complete blood count"
    },
    {
      "text": "Monitor lactate trend (1.3-3.1 mmol/L) to assess tissue perfusion and shock resolution.",
      "action_type": "monitored",
      "target": "lactate"
    },
    {
      "text": "Replete electrolytes as needed, including monitoring potassium (3.8-4.3 mEq/L), magnesium (2.6 mg/dL), and phosphate (3.8 mg/dL).",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Maintain glycemic control with insulin infusion and monitor blood glucose (75-129 mg/dL).",
      "action_type": "therapy_continued",
      "target": "insulin infusion and glucose monitoring"
    },
    {
      "text": "Provide stress ulcer prophylaxis (ranitidine) and DVT prophylaxis as indicated.",
      "action_type": "ordered",
      "target": "stress ulcer and DVT prophylaxis"
    },
    {
      "text": "Continue pulmonary hygiene with incentive spirometry, cough/deep breathing exercises, and subglottic suctioning.",
      "action_type": "therapy_continued",
      "target": "pulmonary hygiene"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue targeted temperature management at 37°C per Arctic Sun settings and monitor core temperature closely.",
      "action_type": "therapy_continued",
      "target": "core temperature / targeted temperature management"
    },
    {
      "text": "Continue mechanical ventilation with lung-protective settings (APV-CMV, tidal volume 450 mL, PEEP 5 cmH2O, FiO2 50%) and monitor airway pressures and minute volume.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue sedation with propofol and fentanyl infusions, titrating to goal RASS -5, and reassess sedation depth.",
      "action_type": "therapy_continued",
      "target": "sedation (propofol/fentanyl)"
    },
    {
      "text": "Monitor arterial blood gas and lactate; repeat ABG to assess oxygenation and ventilation given prior pO2 64 mmHg on FiO2 50%.",
      "action_type": "monitored",
      "target": "arterial blood gas / oxygenation"
    },
    {
      "text": "Monitor coagulation parameters (PTT 94.5 s, INR 1.5) and heparin infusion; adjust heparin per protocol.",
      "action_type": "monitored",
      "target": "coagulation / heparin therapy"
    },
    {
      "text": "Monitor blood glucose and continue insulin/dextrose management per sliding scale, given fingerstick glucose 114-148 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Monitor and replace electrolytes (potassium 3.7 mEq/L, magnesium 2.2 mg/dL, phosphate 3.6 mg/dL) per protocol.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Continue stress ulcer prophylaxis with famotidine and assess GI tolerance.",
      "action_type": "therapy_continued",
      "target": "stress ulcer prophylaxis"
    },
    {
      "text": "Continue antimicrobial therapy (cefepime, vancomycin, metronidazole, ceftazidime) and monitor for infection, given leukocytosis and sputum specimen.",
      "action_type": "therapy_continued",
      "target": "antimicrobial therapy"
    },
    {
      "text": "Perform endotracheal tube care including subglottal suctioning, cuff pressure monitoring, and repositioning to prevent complications.",
      "action_type": "procedure_performed",
      "target": "endotracheal tube / airway"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with lung-protective settings, targeting Richmond-RAS goal of -1 to -2 and assessing readiness for weaning.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue propofol and fentanyl infusions for sedation and analgesia, titrating to Richmond-RAS goal.",
      "action_type": "therapy_continued",
      "target": "sedation and analgesia"
    },
    {
      "text": "Monitor renal function with serial creatinine and urine output; evaluate for acute kidney injury and need for renal replacement therapy.",
      "action_type": "monitored",
      "target": "renal function"
    },
    {
      "text": "Monitor and manage electrolytes, including hypernatremia, hypokalemia, and hyperphosphatemia.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Continue broad-spectrum antibiotics (piperacillin-tazobactam and vancomycin) for suspected infection, with reassessment based on culture results.",
      "action_type": "therapy_continued",
      "target": "antimicrobial therapy"
    },
    {
      "text": "Monitor temperature and inflammatory markers (CRP) to assess response to infection.",
      "action_type": "monitored",
      "target": "infection status"
    },
    {
      "text": "Perform daily assessment of sedation and delirium using Richmond-RAS and CAM-ICU.",
      "action_type": "assessment_performed",
      "target": "sedation and delirium"
    },
    {
      "text": "Implement aspiration precautions, including subglottal suctioning and head-of-bed elevation.",
      "action_type": "treatment_performed",
      "target": "aspiration prevention"
    },
    {
      "text": "Provide pressure ulcer prevention with regular repositioning and skin care, given Braden score indicating risk.",
      "action_type": "treatment_performed",
      "target": "pressure ulcer prevention"
    },
    {
      "text": "Monitor blood counts and coagulation parameters, with consideration for anemia management if clinically indicated.",
      "action_type": "monitored",
      "target": "hematologic status"
    }
  ]
}

{
  "claims": [
    {
      "text": "Monitor arterial blood gas and lactate to assess oxygenation, ventilation, and perfusion.",
      "action_type": "monitored",
      "target": "arterial blood gas and lactate"
    },
    {
      "text": "Monitor hemoglobin and hematocrit for anemia and bleeding.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Monitor platelet count and coagulation studies (PT/PTT/INR).",
      "action_type": "monitored",
      "target": "platelet count and coagulation studies"
    },
    {
      "text": "Monitor serum electrolytes, BUN, creatinine, and glucose.",
      "action_type": "monitored",
      "target": "serum electrolytes, renal function, and glucose"
    },
    {
      "text": "Monitor invasive hemodynamics including arterial blood pressure, central venous pressure, pulmonary artery pressures, and cardiac output.",
      "action_type": "monitored",
      "target": "invasive hemodynamics"
    },
